UPDATE dm_rd_efc_security_metric_detail_conf SET conf_json = '{"rule":{"brief":"检查仓库是否提供安全政策文档 SECURITY.md（检查 .gitcode/、根目录、docs/ 等位置），并对文档内容做三项检测：漏洞披露信息、联系链接、自由文本说明。","formula":"无 SECURITY.md = 0 分；有 SECURITY.md 时三项独立加分：漏洞披露信息 +1、联系链接 +6、自由文本说明 +3（满分 10）","conditions":[{"label":"漏洞披露信息","value":"文档包含漏洞报告相关说明（report / vulnerability / disclosure / exploit / CVE 等关键词）"},{"label":"联系链接","value":"文档包含邮箱或 URL"},{"label":"自由文本说明","value":"文档包含实质性文本内容"}],"naCondition":"无，本指标恒有得分。","notes":[]},"params":{"s1":"1","s6":"6","s3":"3"},"summary":[{"label":"漏洞披露信息","when":"has_file = 1","value":"#bool:$disclosure:满足:未满足","level":"#bool:$disclosure:success:error"},{"label":"联系链接","when":"has_file = 1","value":"#bool:$link:满足:未满足","level":"#bool:$link:success:error"},{"label":"自由文本说明","when":"has_file = 1","value":"#bool:$free_text:满足:未满足","level":"#bool:$free_text:success:error"},{"key":"sat","hidden":true,"when":"has_file = 1","value":"#sat:$disclosure,$link,$free_text"},{"label":"已满足","when":"has_file = 1","value":"#tpl:{s.sat} / 3","level":"#lt:$s.sat:3:error"}],"failNote":"#tpl:评分：三项独立加分 —— 漏洞披露信息 +1、联系链接 +6、自由文本说明 +3 → score = {score}。本指标既不是档位判定，也不是按比例扣分","failEmptyText":"全部满足：仓库内已检出 SECURITY.md，三项检测（漏洞披露信息 / 联系链接 / 自由文本说明）全部满足","dataNote":"三项独立加分：漏洞披露信息 +1、联系链接 +6、自由文本说明 +3。无 SECURITY.md 时按口径记 0 分并参与汇聚（进分母），不是 NA；此时三项检测无执行前提，不展示检测明细，仅展示未检出说明。","failItems":[{"when":"has_file = 0","title":"未检出 SECURITY.md 文件","fields":[{"label":"检索路径","value":".gitcode/SECURITY.md、SECURITY.md、docs/SECURITY.md、security.md"},{"label":"判定","value":"未检出","level":"error"}],"reason":"仓库内未检出 SECURITY.md 文件，三项检测（漏洞披露信息 / 联系链接 / 自由文本说明）无执行前提，未执行，按口径记 0 分","searchText":"SECURITY.md"},{"when":"has_file = 1 && disclosure = 0","title":"未满足：漏洞披露信息","fields":[{"label":"检测项","value":"漏洞披露信息"},{"label":"加分数","value":"#tpl:+{p.s1}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出漏洞披露信息，+1 未得分","searchText":"漏洞披露"},{"when":"has_file = 1 && link = 0","title":"未满足：联系链接","fields":[{"label":"检测项","value":"联系链接"},{"label":"加分数","value":"#tpl:+{p.s6}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出联系链接，+6 未得分","searchText":"联系链接"},{"when":"has_file = 1 && free_text = 0","title":"未满足：自由文本说明","fields":[{"label":"检测项","value":"自由文本说明"},{"label":"加分数","value":"#tpl:+{p.s3}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出自由文本安全说明，+3 未得分","searchText":"自由文本"}],"groups":[{"key":"check","label":"检测项","when":"has_file = 1","columns":[{"label":"检测项","key":"item","type":"text"},{"label":"结果","key":"result","type":"text"},{"label":"加分","key":"score","type":"number"}],"rows":[{"item":"漏洞披露信息","ok":"$disclosure","score":"#tpl:+{p.s1}"},{"item":"联系链接","ok":"$link","score":"#tpl:+{p.s6}"},{"item":"自由文本说明","ok":"$free_text","score":"#tpl:+{p.s3}"}],"cellOf":{"item":{"text":"$item"},"result":{"text":"#bool:$ok:满足:未满足","level":"#bool:$ok:success:error"},"score":{"text":"$score"}},"searchText":"#tpl:{item}"}]}', updated_by = 'ai-assisted', updated_at = NOW() WHERE metric_code = 'SECURITY_POLICY';
